import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Expressions.md","filePath":"manual-zh/Expressions.md","lastUpdated":1785684581000}'),s={name:"manual-zh/Expressions.md"};function o(n,t,_,i,p,l){return e(),a("div",null,[...t[0]||(t[0]=[r('<h2 id="_7-数学表达式" tabindex="-1">7 数学表达式 <a class="header-anchor" href="#_7-数学表达式" aria-label="Permalink to &quot;7 数学表达式&quot;">​</a></h2><p>表达式在 PSPP 命令中每次出现时都遵循共同的语法。表达式由 <em>操作数</em> 组成，操作数可以是数字、字符串或变量名，由 <em>运算符</em> 分隔。有五种类型的运算符：分组、算术、逻辑、关系和函数。</p><p>每个运算符接受一个或多个操作数作为输入，并产生恰好一个结果作为输出。根据运算符的不同，操作数接受字符串或数字作为操作数。除少数例外，操作数本身可以是完整的表达式。</p><table tabindex="0"><thead><tr><th>• 布尔值</th><th></th><th>布尔值</th></tr></thead><tbody><tr><td>• 表达式中的缺失值</td><td></td><td>在表达式中使用缺失值</td></tr><tr><td>• 分组运算符</td><td></td><td>括号</td></tr><tr><td>• 算术运算符</td><td></td><td>加 减 乘 除 幂</td></tr><tr><td>• 逻辑运算符</td><td></td><td>AND NOT OR</td></tr><tr><td>• 关系运算符</td><td></td><td>EQ GE GT LE LT NE</td></tr><tr><td>• 函数</td><td></td><td>更复杂的运算符</td></tr><tr><td>• 运算顺序</td><td></td><td>运算符优先级</td></tr></tbody></table>',4)])])}const c=d(s,[["render",o]]);export{m as __pageData,c as default};
